import os,json,subprocess,re,stat,time
from pathlib import Path
out={"project":"pink-iptv","service":{},"aliases":{},"socket":{},"other":{}}
def show():
 q=subprocess.run(["systemctl","show","pink-vpn","-p","MainPID,NRestarts,ActiveState,SubState,Result,ExecMainStatus,Restart"],capture_output=True,text=True,timeout=7)
 return dict(line.split("=",1) for line in q.stdout.splitlines() if "=" in line)
out["service"]["before"]=show()
sock=Path("/run/pink-vpn/control.sock")
out["socket"]["exists"]=sock.exists()
try:out["socket"]["is_socket"]=stat.S_ISSOCK(sock.stat().st_mode)
except OSError:out["socket"]["is_socket"]=False
try:
 r=subprocess.run(["ss","-H","-lxnp"],capture_output=True,text=True,timeout=9)
 out["socket"]["listening"]=any("/run/pink-vpn/control.sock" in x for x in r.stdout.splitlines())
except Exception:out["socket"]["listening"]=False
time.sleep(2)
out["service"]["after"]=show()
for old in ("/etc/pink-vpn","/var/lib/pink-vpn"):
 p=Path(old)
 out["aliases"][old]={"symlink":p.is_symlink(),"exists":p.exists(),"target":os.readlink(p) if p.is_symlink() else None}
for n in ("ssh","nginx","pink-vpn","pink-iptv-backend","lowcost-europa","fadego-staging","pm2-root","pm2-iptvpn-bot"):
 out["other"][n]=subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip()
print(json.dumps(out,sort_keys=True))
